#include <iostream>
using namespace std;

int main()
{

    int a = 5, b = 8;

    cout << (a < b) << endl;  // prints 1 (true)
    cout << (a == b) << endl; // prints 0 (false)

    string name = "Nathan";
    cout << (name == "Nathan") << endl;
    cout << (name != "Nathan") << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main()
{
    int length, width, area;

    cout << "This program calculates the area "
         << "of a rectangle." << endl;

    cout << "Enter length and width of the rectangle, "
         << "separated by a space: ";
    cin >> length >> width;

    area = length * width;
    cout << "The area of the rectangle is: " << area << endl;

    return 0;
}
